  if (!Array.isArray(arr) || arr.length !== 5) {
    console.log("Input must be an array of 5 numbers.");
    return;
  }

  // Loop through the array and check each number for primality
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];

    // Check if the number is a positive integer
    if (typeof num !== "number" || !Number.isInteger(num) || num <= 0) {
      console.log(`${num} is not a valid number.`);
      continue;
    }

    // Check if the number is prime
    let isPrime = true;
    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }

    // If the number is prime, print it to the console
    if (isPrime) {
      console.log(num);
      return;
    }
  }
}

// Example usage
const numbers = [2, 7, 12, 19, 31];
checkPrimeNumber(numbers);
