    // leer línea por línea del archivo
    while (getline(file, linea)) {
        // contar las apariciones de la palabra en la línea actual
        size_t pos = 0;
        while ((pos = linea.find(palabra, pos)) != string::npos) {
            pos += palabra.length();
            apariciones++;
        }
    }

    // cerrar el archivo
    file.close();

    // imprimir el resultado
    cout << "La palabra \"" << palabra << "\" aparece " << apariciones << " veces en el archivo " << archivo << endl;

    return 0;
}
